   99	    public Javalin create() {
  100	        Javalin app = Javalin.create(config -> config.showJavalinBanner = false);
  101	
  102	        app.post("/checkout/summary", ctx -> json(ctx, 200, checkout.prepare(body(ctx)).summary()));
  103	        app.post("/orders", ctx -> json(ctx, 201, order(orders.register(body(ctx)))));
