  110	                json(ctx, 200, order(r.order()));
  111	            }
  112	        });
  113	        app.post("/orders/{id}/shipment",
  114	                ctx -> json(ctx, 200, order(orders.ship(ctx.pathParam("id"), body(ctx)))));
  115	        app.post("/orders/{id}/delivery", ctx -> json(ctx, 200, order(orders.deliver(ctx.pathParam("id")))));
  116	        app.post("/orders/{id}/cancellation", ctx -> json(ctx, 200, order(orders.cancel(ctx.pathParam("id")))));
  117	        app.get("/products/{sku}", ctx -> json(ctx, 200, queries.product(ctx.pathParam("sku"))));
  118	        app.get("/customers/{cpf}", ctx -> json(ctx, 200, queries.customer(ctx.pathParam("cpf"))));
  119	        app.get("/customers/{cpf}/notifications", ctx -> json(ctx, 200,
  120	                queries.notifications(ctx.pathParam("cpf")).stream().map(Api::notification).toList()));
  121	        app.post("/notifications/{id}/read",
  122	                ctx -> json(ctx, 200, notification(queries.markRead(ctx.pathParam("id")))));
