203	public final class TransLogClient implements CarrierGateway {
204	    private static final Duration TIMEOUT = Duration.ofSeconds(2);
205	
206	    private final String baseUrl;
207	    private final HttpClient http = HttpClient.newBuilder().connectTimeout(TIMEOUT).build();
