218	                    + "&weight_g=" + weightGrams + "&service=" + URLEncoder.encode(service, StandardCharsets.UTF_8));
219	            HttpRequest request = HttpRequest.newBuilder(uri).timeout(TIMEOUT).GET().build();
220	            future = http.sendAsync(request, HttpResponse.BodyHandlers.ofString());
221	            HttpResponse<String> response = future.get(TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
222	            if (response.statusCode() != 200) {
223	                throw new UnavailableException("TransLog answered " + response.statusCode(), null);
224	            }
225	            return parse(Json.MAPPER.readTree(response.body()));
226	        } catch (UnavailableException e) {
227	            throw e;
228	        } catch (InterruptedException e) {
229	            Thread.currentThread().interrupt();
230	            throw new UnavailableException("interrupted", e);
231	        } catch (Exception e) {
232	            throw new UnavailableException("TransLog failed", e);
233	        } finally {
234	            if (future != null) {
235	                future.cancel(true);
236	            }
237	        }
238	    }
