241	        if (body == null || !body.isObject()) {
242	            throw new UnavailableException("unexpected TransLog body", null);
243	        }
244	        if (body.has("error")) {
245	            if (body.get("error").isTextual() && "ZIP_NOT_SERVED".equals(body.get("error").asText())) {
246	                return Optional.empty();
247	            }
