  1	package shop.db;
  2	
  3	import java.math.BigDecimal;
  4	import java.sql.Connection;
  5	import java.sql.PreparedStatement;
  6	import java.sql.ResultSet;
  7	import java.sql.SQLException;
  8	import java.time.OffsetDateTime;
  9	import java.time.ZoneOffset;
 10	import java.util.ArrayList;
 11	import java.util.Collection;
 12	import java.util.LinkedHashMap;
 13	import java.util.List;
 14	import java.util.Map;
 15	import java.util.Optional;
 16	import java.util.TreeSet;
 17	import shop.domain.Customer;
 18	import shop.domain.Json;
 19	import shop.domain.Money;
 20	import shop.domain.Notification;
 21	import shop.domain.NotificationType;
 22	import shop.domain.Order;
 23	import shop.domain.OrderItem;
 24	import shop.domain.OrderStatus;
 25	import shop.domain.Product;
 26	import shop.domain.Summary;
 27	
 28	/** All SQL of the service, bound to one transaction. */
 29	public final class Dao {
 30	    private static final String PRODUCT_COLUMNS = "sku, name, price, weight_kg, stock, discontinued";
 31	
 32	    private final Connection c;
 33	    private final boolean postgres;
 34	
 35	    Dao(Connection c, boolean postgres) {
 36	        this.c = c;
 37	        this.postgres = postgres;
 38	    }
 39	
 40	    // ---- products
 41	
 42	    public Optional<Product> product(String sku) throws SQLException {
 43	        try (PreparedStatement ps = c.prepareStatement("SELECT " + PRODUCT_COLUMNS + " FROM products WHERE sku = ?")) {
 44	            ps.setString(1, sku);
 45	            try (ResultSet rs = ps.executeQuery()) {
 46	                return rs.next() ? Optional.of(product(rs)) : Optional.empty();
 47	            }
 48	        }
 49	    }
 50	
 51	    public Map<String, Product> products(Collection<String> skus) throws SQLException {
 52	        Map<String, Product> result = new LinkedHashMap<>();
 53	        for (String sku : skus) {
 54	            product(sku).ifPresent(p -> result.put(sku, p));
 55	        }
 56	        return result;
 57	    }
 58	
 59	    /** Locks the rows in a fixed (sorted) order so concurrent transactions cannot deadlock. */
 60	    public Map<String, Product> lockProducts(Collection<String> skus) throws SQLException {
 61	        Map<String, Product> result = new LinkedHashMap<>();
 62	        for (String sku : new TreeSet<>(skus)) {
 63	            try (PreparedStatement ps = c.prepareStatement(
 64	                    "SELECT " + PRODUCT_COLUMNS + " FROM products WHERE sku = ? FOR UPDATE")) {
 65	                ps.setString(1, sku);
 66	                try (ResultSet rs = ps.executeQuery()) {
 67	                    if (rs.next()) {
 68	                        result.put(sku, product(rs));
 69	                    }
 70	                }
 71	            }
 72	        }
 73	        return result;
 74	    }
 75	
 76	    public void adjustStock(String sku, int delta) throws SQLException {
 77	        try (PreparedStatement ps = c.prepareStatement("UPDATE products SET stock = stock + ? WHERE sku = ?")) {
 78	            ps.setInt(1, delta);
 79	            ps.setString(2, sku);
 80	            ps.executeUpdate();
 81	        }
 82	    }
 83	
 84	    private static Product product(ResultSet rs) throws SQLException {
 85	        return new Product(rs.getString("sku"), rs.getString("name"), Money.round(rs.getBigDecimal("price")),
 86	                Money.round(rs.getBigDecimal("weight_kg")), rs.getInt("stock"), rs.getBoolean("discontinued"));
 87	    }
 88	
 89	    // ---- customers
 90	
 91	    public void ensureCustomer(String cpf, String email) throws SQLException {
 92	        // atomic "insert if absent" so that two service instances can race safely
 93	        String sql = postgres
 94	                ? "INSERT INTO customers (cpf, email, credit_balance) VALUES (?, ?, 0) ON CONFLICT (cpf) DO NOTHING"
 95	                : "INSERT INTO customers (cpf, email, credit_balance) SELECT CAST(? AS VARCHAR(32)), "
 96	                + "CAST(? AS VARCHAR(255)), 0 WHERE NOT EXISTS (SELECT 1 FROM customers WHERE cpf = ?)";
 97	        try (PreparedStatement ps = c.prepareStatement(sql)) {
 98	            ps.setString(1, cpf);
 99	            ps.setString(2, email);
100	            if (!postgres) {
101	                ps.setString(3, cpf);
102	            }
103	            ps.executeUpdate();
104	        }
105	    }
106	
