288	/** Creates the tables and the initial catalog. Safe to run on every start, from several instances at once. */
289	public final class Schema {
290	    private static final long LOCK_KEY = 7_272_018L;
291	
292	    private static final List<String> DDL = List.of(
293	            "CREATE TABLE IF NOT EXISTS products ("
294	                    + "sku VARCHAR(64) PRIMARY KEY, name VARCHAR(255) NOT NULL, price NUMERIC(12,2) NOT NULL, "
295	                    + "weight_kg NUMERIC(10,2) NOT NULL, stock INTEGER NOT NULL CHECK (stock >= 0), "
296	                    + "discontinued BOOLEAN NOT NULL)",
297	            "CREATE TABLE IF NOT EXISTS customers ("
298	                    + "cpf VARCHAR(32) PRIMARY KEY, email VARCHAR(255) NOT NULL, "
299	                    + "credit_balance NUMERIC(12,2) NOT NULL DEFAULT 0)",
300	            "CREATE TABLE IF NOT EXISTS orders ("
301	                    + "id VARCHAR(36) PRIMARY KEY, cpf VARCHAR(32) NOT NULL, email VARCHAR(255) NOT NULL, "
302	                    + "status VARCHAR(32) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, "
303	                    + "summary TEXT NOT NULL, tracking_code VARCHAR(255))",
304	            "CREATE INDEX IF NOT EXISTS idx_orders_cpf_status ON orders (cpf, status)",
305	            "CREATE TABLE IF NOT EXISTS order_items ("
306	                    + "order_id VARCHAR(36) NOT NULL REFERENCES orders (id), line_no INTEGER NOT NULL, "
307	                    + "sku VARCHAR(64) NOT NULL, quantity INTEGER NOT NULL, PRIMARY KEY (order_id, line_no))",
308	            "CREATE TABLE IF NOT EXISTS payment_events ("
309	                    + "order_id VARCHAR(36) NOT NULL, transaction_id VARCHAR(255) NOT NULL, "
310	                    + "outcome VARCHAR(32) NOT NULL, PRIMARY KEY (order_id, transaction_id))",
311	            "CREATE TABLE IF NOT EXISTS notifications ("
312	                    + "seq BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, id VARCHAR(36) NOT NULL UNIQUE, "
313	                    + "cpf VARCHAR(32) NOT NULL, notif_type VARCHAR(32) NOT NULL, order_id VARCHAR(36) NOT NULL, "
314	                    + "status VARCHAR(8) NOT NULL)",
315	            "CREATE INDEX IF NOT EXISTS idx_notifications_cpf ON notifications (cpf)");
316	
317	    private static final String[][] CATALOG = {
318	            {"CAM-001", "Camiseta básica", "79.90", "0.30", "50", "false"},
319	            {"TEN-001", "Tênis corrida", "249.90", "1.20", "10", "false"},
320	            {"FON-001", "Fone sem fio", "199.90", "0.25", "5", "false"},
321	            {"MEI-001", "Meia esportiva", "19.90", "0.10", "100", "false"},
322	            {"JAQ-001", "Jaqueta corta-vento", "389.90", "0.80", "3", "false"},
323	            {"MOC-001", "Mochila urbana", "159.90", "0.90", "1", "false"},
324	            {"BON-001", "Boné aba reta", "59.90", "0.15", "0", "false"},
325	            {"REL-001", "Relógio digital", "129.90", "0.20", "8", "true"}};
326	
327	    private Schema() {
328	    }
329	
330	    public static void init(DataSource dataSource) throws SQLException {
331	        try (Connection c = dataSource.getConnection()) {
332	            c.setAutoCommit(true);
333	            boolean postgres = c.getMetaData().getDatabaseProductName().toLowerCase().contains("postgres");
334	            if (postgres) {
335	                // serializes concurrent starts of several instances
336	                try (Statement s = c.createStatement()) {
337	                    s.execute("SELECT pg_advisory_lock(" + LOCK_KEY + ")");
338	                }
339	            }
340	            try {
341	                try (Statement s = c.createStatement()) {
342	                    for (String ddl : DDL) {
343	                        s.execute(ddl);
344	                    }
345	                }
346	                seedCatalog(c);
347	            } finally {
348	                if (postgres) {
349	                    try (Statement s = c.createStatement()) {
350	                        s.execute("SELECT pg_advisory_unlock(" + LOCK_KEY + ")");
351	                    }
352	                }
353	            }
354	        }
355	    }
356	
357	    private static void seedCatalog(Connection c) throws SQLException {
358	        String sql = "INSERT INTO products (sku, name, price, weight_kg, stock, discontinued) "
359	                + "SELECT CAST(? AS VARCHAR(64)), CAST(? AS VARCHAR(255)), CAST(? AS NUMERIC(12,2)), "
360	                + "CAST(? AS NUMERIC(10,2)), CAST(? AS INTEGER), CAST(? AS BOOLEAN) "
361	                + "WHERE NOT EXISTS (SELECT 1 FROM products WHERE sku = ?)";
362	        try (var ps = c.prepareStatement(sql)) {
363	            for (String[] row : CATALOG) {
364	                ps.setString(1, row[0]);
365	                ps.setString(2, row[1]);
366	                ps.setBigDecimal(3, new java.math.BigDecimal(row[2]));
367	                ps.setBigDecimal(4, new java.math.BigDecimal(row[3]));
368	                ps.setInt(5, Integer.parseInt(row[4]));
369	                ps.setBoolean(6, Boolean.parseBoolean(row[5]));
370	                ps.setString(7, row[0]);
371	                ps.executeUpdate();
372	            }
373	        }
374	    }
375	}
