247	    public List<Notification> notifications(String cpf) throws SQLException {
248	        List<Notification> result = new ArrayList<>();
249	        try (PreparedStatement ps = c.prepareStatement(
250	                "SELECT id, cpf, notif_type, order_id, status FROM notifications WHERE cpf = ? ORDER BY seq")) {
251	            ps.setString(1, cpf);
252	            try (ResultSet rs = ps.executeQuery()) {
253	                while (rs.next()) {
254	                    result.add(notification(rs));
255	                }
256	            }
257	        }
258	        return result;
259	    }
260	
261	    public Optional<Notification> markRead(String id) throws SQLException {
262	        try (PreparedStatement ps = c.prepareStatement("UPDATE notifications SET status = 'READ' WHERE id = ?")) {
263	            ps.setString(1, id);
264	            ps.executeUpdate();
265	        }
266	        try (PreparedStatement ps = c.prepareStatement(
267	                "SELECT id, cpf, notif_type, order_id, status FROM notifications WHERE id = ?")) {
268	            ps.setString(1, id);
269	            try (ResultSet rs = ps.executeQuery()) {
270	                return rs.next() ? Optional.of(notification(rs)) : Optional.empty();
271	            }
272	        }
273	    }
274	
275	    private static Notification notification(ResultSet rs) throws SQLException {
276	        return new Notification(rs.getString(1), rs.getString(2), NotificationType.valueOf(rs.getString(3)),
277	                rs.getString(4), rs.getString(5));
278	    }
279	}
