378	import java.sql.Connection;
379	import java.sql.SQLException;
380	import javax.sql.DataSource;
381	
382	public final class Database {
383	    @FunctionalInterface
384	    public interface Work<T> {
385	        T run(Dao dao) throws SQLException;
386	    }
387	
388	    private final DataSource dataSource;
389	
390	    private final boolean postgres;
391	
392	    public Database(DataSource dataSource) {
393	        this.dataSource = dataSource;
394	        try (Connection c = dataSource.getConnection()) {
395	            this.postgres = c.getMetaData().getDatabaseProductName().toLowerCase().contains("postgres");
396	        } catch (SQLException e) {
397	            throw new DbException(e);
398	        }
399	    }
400	
401	    /** Runs the work in one transaction: commits if it returns, rolls back if it throws. */
402	    public <T> T tx(Work<T> work) {
403	        try (Connection connection = dataSource.getConnection()) {
404	            connection.setAutoCommit(false);
405	            try {
406	                T result = work.run(new Dao(connection, postgres));
407	                connection.commit();
408	                return result;
409	            } catch (Throwable e) {
410	                try {
411	                    connection.rollback();
412	                } catch (SQLException suppressed) {
413	                    e.addSuppressed(suppressed);
414	                }
415	                throw e;
416	            }
417	        } catch (SQLException e) {
418	            throw new DbException(e);
419	        }
420	    }
421	}

