136	import java.math.BigDecimal;
137	import java.math.MathContext;
138	
139	public interface PaymentMethod {
140	    record Settlement(BigDecimal finalTotal, BigDecimal installmentAmount) {
141	    }
142	
143	    String code();
144	
145	    boolean acceptsInstallments(int installments);
146	
147	    /** Refuses with PAYMENT_METHOD_UNAVAILABLE when the method cannot be used for this total. */
148	    default void checkAvailable(BigDecimal orderTotal) {
149	    }
150	
151	    Settlement settle(BigDecimal orderTotal, int installments, boolean couponUsed);
152	
153	    record Pix(String code, BigDecimal discountRate) implements PaymentMethod {
154	        @Override
155	        public boolean acceptsInstallments(int n) {
156	            return n == 1;
157	        }
158	
159	        @Override
160	        public Settlement settle(BigDecimal total, int n, boolean couponUsed) {
161	            BigDecimal discount = couponUsed ? Money.ZERO : Money.round(total.multiply(discountRate));
162	            BigDecimal result = total.subtract(discount);
163	            return new Settlement(result, result);
164	        }
165	    }
166	
167	    record BankSlip(String code, BigDecimal fee, BigDecimal maximumTotal) implements PaymentMethod {
168	        @Override
169	        public boolean acceptsInstallments(int n) {
170	            return n == 1;
171	        }
172	
173	        @Override
174	        public void checkAvailable(BigDecimal total) {
175	            if (total.compareTo(maximumTotal) > 0) {
176	                throw ApiException.unprocessable("PAYMENT_METHOD_UNAVAILABLE");
177	            }
178	        }
179	
180	        @Override
181	        public Settlement settle(BigDecimal total, int n, boolean couponUsed) {
182	            BigDecimal result = total.add(fee);
183	            return new Settlement(result, result);
184	        }
185	    }
186	
187	    /** Interest-free up to {@code freeUntil} installments, then Price table. */
188	    record CreditCard(String code, int maxInstallments, int freeUntil, BigDecimal monthlyRate)
189	            implements PaymentMethod {
190	        @Override
191	        public boolean acceptsInstallments(int n) {
192	            return n >= 1 && n <= maxInstallments;
193	        }
194	
195	        @Override
196	        public Settlement settle(BigDecimal total, int n, boolean couponUsed) {
197	            if (n <= freeUntil) {
198	                return new Settlement(total, Money.round(total.divide(BigDecimal.valueOf(n), MathContext.DECIMAL128)));
199	            }
200	            BigDecimal growth = BigDecimal.ONE.add(monthlyRate).pow(n, MathContext.DECIMAL128);
201	            // total * i / (1 - (1+i)^-n)  ==  total * i * (1+i)^n / ((1+i)^n - 1)
202	            BigDecimal installment = Money.round(total.multiply(monthlyRate).multiply(growth)
203	                    .divide(growth.subtract(BigDecimal.ONE), MathContext.DECIMAL128));
204	            return new Settlement(installment.multiply(BigDecimal.valueOf(n)), installment);
205	        }
206	    }
207	}
