216	/** The only place that says which operation is allowed in which status. */
217	public final class OrderLifecycle {
218	    public enum Operation { PAY, SHIP, DELIVER, CANCEL }
219	
220	    private static final Map<Operation, Map<OrderStatus, OrderStatus>> TRANSITIONS = new EnumMap<>(Operation.class);
221	
222	    static {
223	        TRANSITIONS.put(Operation.PAY, Map.of(AWAITING_PAYMENT, PAID));
224	        TRANSITIONS.put(Operation.SHIP, Map.of(PAID, SHIPPED));
225	        TRANSITIONS.put(Operation.DELIVER, Map.of(SHIPPED, DELIVERED));
226	        TRANSITIONS.put(Operation.CANCEL, Map.of(AWAITING_PAYMENT, CANCELLED, PAID, CANCELLED));
227	    }
228	
229	    private OrderLifecycle() {
230	    }
231	
232	    public static Optional<OrderStatus> next(OrderStatus current, Operation operation) {
233	        return Optional.ofNullable(TRANSITIONS.get(operation).get(current));
234	    }
235	
236	    /** Returns the next status or refuses with OPERATION_NOT_ALLOWED. */
237	    public static OrderStatus require(OrderStatus current, Operation operation) {
238	        return next(current, operation).orElseThrow(() -> ApiException.conflict("OPERATION_NOT_ALLOWED"));
239	    }
240	}
