272	import com.fasterxml.jackson.core.JsonGenerator;
273	
274	public final class Json {
275	    public static final ObjectMapper MAPPER = new ObjectMapper()
276	            .enable(JsonGenerator.Feature.WRITE_BIGDECIMAL_AS_PLAIN)
277	            .disable(SerializationFeature.FAIL_ON_EMPTY_BEANS);
278	
279	    private Json() {
280	    }
281	
282	    public static String write(Object value) {
283	        try {
284	            return MAPPER.writeValueAsString(value);
285	        } catch (JsonProcessingException e) {
286	            throw new IllegalStateException(e);
287	        }
288	    }
289	
290	    public static <T> T read(String text, Class<T> type) {
291	        try {
292	            return MAPPER.readValue(text, type);
293	        } catch (JsonProcessingException e) {
294	            throw new IllegalStateException(e);
295	        }
296	    }
297	
298	    /** Parses a request body; anything that is not valid JSON becomes a missing node. */
299	    public static JsonNode parseLenient(String text) {
300	        if (text == null || text.isBlank()) {
301	            return MissingNode.getInstance();
302	        }
303	        try {
304	            return MAPPER.readTree(text);
305	        } catch (JsonProcessingException e) {
306	            return MissingNode.getInstance();
307	        }
308	    }
309	}
