330	/** Lookup of pluggable business rules by their code. */
331	public final class Registry<T> {
332	    private final Map<String, T> byCode = new LinkedHashMap<>();
333	
334	    public Registry(Function<T, String> codeOf, Iterable<? extends T> items) {
335	        for (T item : items) {
336	            byCode.put(codeOf.apply(item), item);
337	        }
338	    }
339	
340	    public Optional<T> find(String code) {
341	        return code == null ? Optional.empty() : Optional.ofNullable(byCode.get(code));
342	    }
