167	    record BankSlip(String code, BigDecimal fee, BigDecimal maximumTotal) implements PaymentMethod {
168	        @Override
169	        public boolean acceptsInstallments(int n) {
170	            return n == 1;
171	        }
172	
173	        @Override
174	        public void checkAvailable(BigDecimal total) {
175	            if (total.compareTo(maximumTotal) > 0) {
