import com.sun.net.httpserver.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

public class Stub {
    static volatile String body = "{\"price_cents\": 3310, \"eta_hours\": 41}";
    static volatile int status = 200;
    static volatile long delayMs = 0;
    static final List<String> log = new CopyOnWriteArrayList<>();

    static Map<String,String> q(String s) {
        Map<String,String> m = new HashMap<>();
        if (s == null) return m;
        for (String p : s.split("&")) { String[] kv = p.split("=", 2); m.put(URLDecoder.decode(kv[0], StandardCharsets.UTF_8), kv.length > 1 ? URLDecoder.decode(kv[1], StandardCharsets.UTF_8) : ""); }
        return m;
    }
    static void send(HttpExchange ex, int st, String b) throws java.io.IOException {
        byte[] bytes = b.getBytes(StandardCharsets.UTF_8);
        ex.getResponseHeaders().add("Content-Type", "application/json");
        ex.sendResponseHeaders(st, bytes.length);
        ex.getResponseBody().write(bytes); ex.close();
    }
    public static void main(String[] a) throws Exception {
        HttpServer s = HttpServer.create(new InetSocketAddress(Integer.parseInt(a[0])), 0);
        s.setExecutor(Executors.newCachedThreadPool());
        s.createContext("/v2/quote", ex -> {
            log.add(ex.getRequestURI().getRawQuery());
            try { if (delayMs > 0) Thread.sleep(delayMs); } catch (InterruptedException e) {}
            try { send(ex, status, body); } catch (Exception e) {}
        });
        s.createContext("/_set", ex -> {
            Map<String,String> m = q(ex.getRequestURI().getRawQuery());
            if (m.containsKey("body")) body = m.get("body");
            if (m.containsKey("status")) status = Integer.parseInt(m.get("status"));
            if (m.containsKey("delay")) delayMs = Long.parseLong(m.get("delay"));
            log.clear();
            send(ex, 200, "ok");
        });
        s.createContext("/_log", ex -> send(ex, 200, String.join("\n", log)));
        s.start();
        System.out.println("stub up");
    }
}
