cat >> /tmp/run/h.sh <<'EOF'
J() { sed 's/ [0-9]*$//'; }
stockv() { curl -s $S1/products/$1 | jq .stock; }
# race <label> <cpfprefix> <items-json>...   (one items json per order)
race() {
  local label=$1 pfx=$2; shift 2; local ids=() cas=() cpfs=() k=0
  for items in "$@"; do k=$((k+1)); local cpf=${pfx}$(printf '%02d' $k)
    local R=$(post $S1/orders '{"customer":{"cpf":"'$cpf'","email":"c@x.com"},"items":'"$items"',"zipCode":"01310100","region":"SOUTHEAST","shippingMethod":"STORE_PICKUP","paymentMethod":"CREDIT_CARD","clubTier":"SILVER"}' | J)
    ids+=($(echo "$R" | jq -r .id)); cas+=($(echo "$R" | jq -r .createdAt)); cpfs+=($cpf); done
  rm -f /tmp/run/r8_*
  for i in "${!ids[@]}"; do H=$([ $((i%2)) = 0 ] && echo $S1 || echo $S2)
    (post $H/orders/${ids[$i]}/payment '{"transactionId":"TX-'${ids[$i]:0:8}'","paidAt":"'${cas[$i]}'"}' > /tmp/run/r8_$i) & done; wait 2>/dev/null
  local ok=0 lost=0 bad=0
  for i in "${!ids[@]}"; do local r=$(cat /tmp/run/r8_$i)
    local st=$(curl -s $S1/orders/${ids[$i]} | jq -r .status); local nt=$(curl -s $S1/customers/${cpfs[$i]}/notifications | jq -c '[.[].type]'); local cr=$(curl -s $S1/customers/${cpfs[$i]} | jq .creditBalance)
    case "$r" in
      *'"status":"PAID"'*' 200') [ "$st" = PAID ] && [ "$nt" = '["PAYMENT_APPROVED"]' ] && ok=$((ok+1)) || { bad=$((bad+1)); echo "  odd winner: $st $nt"; } ;;
      '{"error":"INSUFFICIENT_STOCK"} 409') [ "$st" = CANCELLED ] && [ "$nt" = '["ORDER_CANCELLED"]' ] && [ "$cr" = "0.00" ] && lost=$((lost+1)) || { bad=$((bad+1)); echo "  odd loser: $st $nt $cr"; } ;;
      *) bad=$((bad+1)); echo "  unexpected: $r";;
    esac; done
  # repeat a loser's notice
  local rep=""; for i in "${!ids[@]}"; do if grep -q INSUFFICIENT /tmp/run/r8_$i; then rep=$(post $S2/orders/${ids[$i]}/payment '{"transactionId":"TX-'${ids[$i]:0:8}'","paidAt":"'${cas[$i]}'"}'); break; fi; done
  echo "$label: winners=$ok losers(409 INSUFFICIENT_STOCK+CANCELLED+notice)=$lost anomalies=$bad ; loser repeat -> $rep"
}
EOF
